def conv_b(aa,bb):
    if(aa==0):
        return ""
    elif(aa%bb>=10):
        return conv_b(aa//bb,bb)+chr(aa%bb+55)
    else:
        return conv_b(aa//bb,bb)+str(aa%bb)

print(conv_b(291,16))

